CREATE OR REPLACE FUNCTION ops._stamp_capture_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  cand uuid;
  found_org uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;  -- app already stamped the chosen org — hot-path no-op
  END IF;

  -- (2) the acting user's personal org — LOOKUP ONLY. First candidate that
  -- already HAS one wins. No auth.users read, no organization created, no
  -- membership written: a forensic row must never manufacture tenancy, and on
  -- the error path it must never wait behind a lock on a catalog table.
  FOREACH cand IN ARRAY ARRAY[NEW.created_by, NEW.user_id, (select auth.uid())]
  LOOP
    CONTINUE WHEN cand IS NULL;
    SELECT o.id INTO found_org
      FROM iam.organizations o
     WHERE o.created_by = cand
       AND o.is_personal IS TRUE
     LIMIT 1;
    IF found_org IS NOT NULL THEN
      NEW.organization_id := found_org;
      RETURN NEW;
    END IF;
  END LOOP;

  -- (3) no candidate owns a personal org (or genuinely system context): the
  -- SYSTEM org. NEVER NULL (db-rules §2). Announced, never silent — the real
  -- actor is still on the row in user_id/created_by.
  NEW.organization_id := '39c38960-d30c-4840-b0c1-c9960de95582'::uuid;
  IF NEW.created_by IS NOT NULL OR NEW.user_id IS NOT NULL THEN
    NEW.metadata := COALESCE(NEW.metadata, '{}'::jsonb) || jsonb_build_object(
      '_org_stamp',
      'system_org_fallback: the acting user has no personal organization row; '
      || 'the capture lane looks one up, it never creates one'
    );
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION platform.inherit_org_from_parent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_ps text := TG_ARGV[0];
  v_pt text := TG_ARGV[1];
  v_fk text := TG_ARGV[2];
  v_fkval uuid;
  v_org uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  EXECUTE format('SELECT ($1).%I', v_fk) INTO v_fkval USING NEW;
  IF v_fkval IS NOT NULL THEN
    EXECUTE format('SELECT organization_id FROM %I.%I WHERE id = $1', v_ps, v_pt)
      INTO v_org USING v_fkval;
    NEW.organization_id := v_org;
  END IF;
  RETURN NEW;  -- if still null, the NOT NULL constraint surfaces the bug loudly
END $function$

CREATE OR REPLACE FUNCTION platform.stamp_run_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_owner uuid; v_system uuid;
begin
  if NEW.organization_id is not null then return NEW; end if;
  v_owner := coalesce(
    nullif(to_jsonb(NEW)->>'created_by','')::uuid,
    nullif(to_jsonb(NEW)->>'user_id','')::uuid,
    nullif(to_jsonb(NEW)->>'triggered_by','')::uuid);
  if v_owner is not null then
    NEW.organization_id := coalesce(
      (select id from iam.organizations where created_by = v_owner and is_personal order by created_at limit 1),
      public.ensure_personal_organization(v_owner));
  else
    select id into v_system from iam.organizations where is_system order by created_at limit 1;
    if v_system is null then
      raise exception 'stamp_run_org: no system organization configured (organizations.is_system)';
    end if;
    NEW.organization_id := v_system;
  end if;
  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public._stamp_org_default()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  j jsonb;
  actor uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;  -- app already stamped the chosen org — hot-path no-op
  END IF;
  j := to_jsonb(NEW);
  actor := COALESCE(
    NULLIF(j->>'created_by','')::uuid,
    NULLIF(j->>'user_id','')::uuid,
    NULLIF(j->>'owner_id','')::uuid,
    (SELECT auth.uid())
  );
  -- A NULL actor means a row with neither org nor owner reached the DB — a real
  -- bug; leave org NULL so the not-null constraint screams, never mis-attribute.
  IF actor IS NOT NULL THEN
    NEW.organization_id := public.ensure_personal_organization(actor);
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.files_inherit_org_from_folder()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.organization_id IS NULL AND NEW.parent_folder_id IS NOT NULL THEN
        SELECT organization_id INTO NEW.organization_id
        FROM files.folders
        WHERE id = NEW.parent_folder_id;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION users._stamp_secret_audit_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org   uuid;
  v_owner uuid;
  cand    uuid;
BEGIN
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.user_secret_id IS NOT NULL THEN
    SELECT s.organization_id, s.user_id
      INTO v_org, v_owner
      FROM users.user_secrets s
     WHERE s.id = NEW.user_secret_id;
    IF v_org IS NOT NULL THEN
      NEW.organization_id := v_org;
      RETURN NEW;
    END IF;
  END IF;

  FOREACH cand IN ARRAY ARRAY[v_owner, NEW.user_id, NEW.actor_id, (select auth.uid())]
  LOOP
    CONTINUE WHEN cand IS NULL;
    BEGIN
      NEW.organization_id := public._d31_impl_ensure_personal_organization(cand);
    EXCEPTION WHEN OTHERS THEN
      NEW.organization_id := NULL;
    END;
    IF NEW.organization_id IS NOT NULL THEN
      RETURN NEW;
    END IF;
  END LOOP;

  NEW.organization_id := '39c38960-d30c-4840-b0c1-c9960de95582'::uuid;
  RETURN NEW;
END
$function$
